-- ------------------------------------------------------
-- Table structure for table `giaodich`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `giaodich`;
CREATE TABLE `giaodich` (
  `giaodich_id` int NOT NULL AUTO_INCREMENT,
  `yeucauhotro_id` int DEFAULT NULL,
  `lichtrano_id` int DEFAULT NULL COMMENT 'Lien ket ky tra neu loaigiaodich=Thu hoi no',
  `quy_id` int NOT NULL,
  `loaigiaodich` enum('Thu','Chi','Thu hoi no') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Thu' COMMENT 'Thu=nhan tai tro, Chi=giai ngan, Thu hoi no=thu hoi von vay',
  `hangmucchi` enum('Tai_tro_cho_vay','Tham_dinh_du_an','Bo_may_hoat_dong','Nhiem_vu_khac') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Chi ap dung khi loaigiaodich=Chi',
  `nguoinhan_id` int DEFAULT NULL,
  `sotien` decimal(15,2) NOT NULL,
  `hinhthuc` enum('Tien mat','Chuyen khoan') COLLATE utf8mb4_unicode_ci NOT NULL,
  `magiaodich` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chungtu` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trangthai` enum('Thanh cong','That bai','Dang xu ly') COLLATE utf8mb4_unicode_ci DEFAULT 'Dang xu ly',
  `doisoattrangthai` enum('Chua_doi_soat','Da_doi_soat','Bat_thuong') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Chua_doi_soat',
  `sotienthucte` decimal(15,2) DEFAULT NULL,
  `doisoatboiid` int DEFAULT NULL,
  `doisoatluc` datetime DEFAULT NULL,
  `doisoatghichu` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ghichu` text COLLATE utf8mb4_unicode_ci,
  `nguoithuchien_id` int NOT NULL,
  `ngaygiaodich` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ngaycapnhat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`giaodich_id`),
  KEY `idx_yeucauhotro` (`yeucauhotro_id`),
  KEY `idx_quy` (`quy_id`),
  KEY `idx_nguoinhan` (`nguoinhan_id`),
  KEY `nguoithuchien_id` (`nguoithuchien_id`),
  KEY `fk_doisoatboiid` (`doisoatboiid`),
  CONSTRAINT `fk_doisoatboiid` FOREIGN KEY (`doisoatboiid`) REFERENCES `nguoidung` (`nguoidung_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `giaodich_ibfk_1` FOREIGN KEY (`yeucauhotro_id`) REFERENCES `yeucauhotro` (`yeucauhotro_id`) ON UPDATE CASCADE,
  CONSTRAINT `giaodich_ibfk_2` FOREIGN KEY (`quy_id`) REFERENCES `quy` (`quy_id`) ON UPDATE CASCADE,
  CONSTRAINT `giaodich_ibfk_3` FOREIGN KEY (`nguoinhan_id`) REFERENCES `nguoidung` (`nguoidung_id`) ON UPDATE CASCADE,
  CONSTRAINT `giaodich_ibfk_4` FOREIGN KEY (`nguoithuchien_id`) REFERENCES `nguoidung` (`nguoidung_id`) ON UPDATE CASCADE
);

