);

INSERT INTO `guest_yeucauhotro` (`guest_yeucauhotro_id`, `guest_hoten`, `guest_email`, `guest_sodienthoai`, `vaitro`, `guest_mssv`, `guest_khoa`, `guest_lop`, `guest_sotaikhoan`, `guest_nganhang`, `guest_chutaikhoan`, `quy_id`, `lydo`, `sotiendenghi`, `loaihotro`, `tongkinhphidudan`, `tailieudinhkem`, `trang_thai_staging`, `yeucauhotro_id_ref`, `nguoidung_id_ref`, `otp_code`, `otp_expires_at`, `is_email_verified`, `tracking_uuid`, `ngaytao`, `ngaycapnhat`) VALUES
(1, 'Trần Nhựt Thiên', 'nthienwww@gmail.com', '0363489827', 'sinh_vien', '110122162', 'Công nghệ Thông tin', 'DA22TTC', '0763885417', 'BIDV', 'TRAN NHUT THIEN', 26, '[Đơn xin Quỹ Chuyển giao Công nghệ & Ứng dụng thực tiễn học kỳ II năm học 2026-2027] - **CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM**\n**Độc lập – Tự do – Hạnh phúc**\n***\n*Trà Vinh, ngày [Ngày] tháng [Tháng] năm [Năm]*\n\n**ĐƠN ĐỀ NGHỊ VAY VỐN HỖ TRỢ DỰ ÁN KHOA HỌC**\n\n**Kính gửi:**\n*   **Ban Quản lý Quỹ Chuyển giao Công nghệ & Ứng dụng thực tiễn, Trường Đại học Trà Vinh**\n*   **Ban Giám hiệu Trường Đại học Trà Vinh**\n\nEm tên là: **[Họ và tên sinh viên]**\nNgày sinh: **[Ngày/tháng/năm sinh]**\nMã số sinh viên (MSSV): **[Mã số sinh viên]**\nLớp: **[Tên lớp]**, Khoa: **[Tên khoa]**\nĐiện thoại: **[Số điện thoại]**\nEmail: **[Địa chỉ Email]**\nGiảng viên hướng dẫn: **[Họ và tên Giảng viên hướng dẫn]** (Nếu có)\n\nEm viết đơn này với lòng kính trọng và mong muốn nhận được sự xem xét, hỗ trợ từ Quỹ Chuyển giao Công nghệ & Ứng dụng thực tiễn của Nhà trường.\n\nKính thưa Quý Ban,\nTrong suốt quá trình học tập tại Trường Đại học Trà Vinh, em luôn ấp ủ niềm đam mê với nghiên cứu khoa học và mong muốn được đóng góp những kiến thức đã học vào việc phát triển các ứng dụng thực tiễn, đặc biệt trong lĩnh vực nông nghiệp – thủy sản tại khu vực Đồng bằng sông Cửu Long, vốn là thế mạnh của Nhà trường và địa phương. Em đã có những ý tưởng ban đầu và bước đầu tìm hiểu về dự án **[Tên dự án giả định, ví dụ: "Nghiên cứu ứng dụng chế phẩm sinh học thân thiện môi trường trong nuôi tôm thẻ chân trắng thâm canh"]**. Em tin rằng dự án này có tiềm năng ứng dụng cao, giúp cải thiện hiệu quả sản xuất và giảm thiểu tác động tiêu cực đến môi trường, đúng theo định hướng của Quỹ.\n\nTuy nhiên, hoàn cảnh gia đình em hiện đang gặp nhiều khó khăn. Gia đình em chủ yếu làm nông nghiệp với thu nhập bấp bênh, không đủ để trang trải các chi phí sinh hoạt thiết yếu và học phí của em. Tình hình tài chính eo hẹp đã và đang là rào cản lớn, gây ảnh hưởng không nhỏ đến khả năng tập trung vào học tập và phát triển các ý tưởng nghiên cứu. Em rất mong muốn có thể dành trọn tâm huyết cho việc học tập và thực hiện dự án này, nhưng nguồn lực tài chính hạn chế khiến em gặp rất nhiều khó khăn trong việc tiếp cận các tài liệu, trang thiết bị ban đầu và duy trì cuộc sống sinh viên.\n\nVới tinh thần cầu tiến và khát khao được cống hiến, em đã tìm hiểu về Quỹ Chuyển giao Công nghệ & Ứng dụng thực tiễn. Em hiểu rằng Quỹ hoạt động dưới hình thức cho vay vốn có hoàn trả, với mục tiêu hỗ trợ các hoạt động hoàn thiện công nghệ, thử nghiệm sản xuất và thương mại hóa các kết quả nghiên cứu khoa học. Dù hoàn cảnh khó khăn, em vẫn tin tưởng vào khả năng của bản thân và sự hướng dẫn của thầy cô để thực hiện thành công dự án của mình, từ đó tạo ra giá trị thiết thực và có nguồn thu để hoàn trả vốn vay theo đúng cam kết.\n\nVới những lý do trên, em kính mong Quý Ban xem xét và tạo điều kiện cho em được vay vốn từ Quỹ để có thể tiếp tục hoàn thiện và triển khai dự án **[Tên dự án giả định]**. Em cam kết sẽ chuẩn bị đầy đủ các hồ sơ theo yêu cầu của Quỹ, bao gồm thuyết minh dự án chi tiết, minh chứng kết quả nghiên cứu ban đầu, dự toán kinh phí sử dụng vốn vay và phương án hoàn trả vốn vay rõ ràng, khả thi. Đồng thời, em cam kết sử dụng nguồn vốn vay đúng mục đích, tuân thủ nghiêm ngặt tiến độ triển khai dự án, các quy định của Quỹ và Nhà trường về việc hoàn trả gốc và lãi đúng hạn.\n\nEm xin chân thành bày tỏ lòng biết ơn sâu sắc đến Ban Giám hiệu Nhà trường và Ban Quản lý Quỹ đã luôn quan tâm, tạo điều kiện hỗ trợ sinh viên trong quá trình học tập và nghiên cứu. Em rất mong nhận được phản hồi từ Quý Ban.\n\nKính chúc Quý Ban luôn dồi dào sức khỏe và thành công trong công tác.\n\nTrân trọng kính chào!\n\n**Người làm đơn**\n*(Ký và ghi rõ họ tên)*\n\n**[Họ và tên sinh viên]**', '20000000.00', 'Tai tro khong hoan lai', NULL, 'uploads/documents/TranNhutThienCV_1784311508748_284143772.pdf', 'DA_CHUYEN', 1, 9, NULL, NULL, 1, '2c04aa4b-ec96-42a3-a2f2-6258912c7c96', '2026-07-17 18:10:42', '2026-07-17 18:10:45'),
(2, 'Hà Văn Khâu', 'khauha65@gmail.com', '0743836852', 'sinh_vien', '110123274', 'Nông nghiệp Thủy sản', 'DA22TSB', '09876543210', 'MbBank', 'HA VAN KHAU', 27, '[Đơn xin hổ trợ vay vốn xây dựng mô hình trông cây công nghệ nhà kính] - Nhằm phát triển mô hình trồng cây trong nhà kính ứng dụng công nghệ cao, tôi đề nghị được vay vốn có thu hồi để đầu tư xây dựng hệ thống nhà kính, hệ thống tưới nhỏ giọt tự động, thiết bị kiểm soát nhiệt độ, độ ẩm và mua cây giống, vật tư nông nghiệp chất lượng cao. Việc đầu tư mô hình này giúp nâng cao năng suất, chất lượng nông sản, giảm thiểu ảnh hưởng của thời tiết, hạn chế sâu bệnh và tiết kiệm chi phí sản xuất trong dài hạn.\n\nSau khi mô hình đi vào hoạt động ổn định, nguồn thu từ việc sản xuất và tiêu thụ nông sản sẽ được sử dụng để hoàn trả khoản vay theo đúng thời hạn cam kết. Dự án không chỉ góp phần tạo nguồn thu nhập ổn định, nâng cao kỹ năng ứng dụng công nghệ cao trong nông nghiệp mà còn có tiềm năng mở rộng quy mô, tạo việc làm và đóng góp vào sự phát triển của nền nông nghiệp bền vững tại địa phương.', '50000000.00', 'Tai tro co thu hoi', '300000000.00', 'uploads/documents/TranNhutThienCV_1784354027388_352665590.pdf', 'DA_CHUYEN', 2, 10, NULL, NULL, 1, 'e45ef228-05f3-460f-bb0a-cf240387a4d3', '2026-07-18 05:54:26', '2026-07-18 05:54:30'),
(3, 'Thạch Phan Dựng', 'ditden39@gmail.com', '0939964322', 'sinh_vien', '1101132456', 'Y tế', 'DÁ22YTA', '0987654567876', 'VietcomBank', 'THACH PHAN DUNG', 28, '[Đơn xin Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng cho sinh viên nghèo] - Nhằm đảm bảo điều kiện học tập và nâng cao chất lượng cuộc sống cho sinh viên có hoàn cảnh khó khăn, tôi đề nghị được hỗ trợ chi phí khám sức khỏe định kỳ. Việc khám sức khỏe giúp phát hiện sớm các vấn đề về thể chất, từ đó có biện pháp điều trị và phòng ngừa kịp thời, giúp sinh viên duy trì sức khỏe ổn định để học tập và rèn luyện.\n\nDo điều kiện kinh tế gia đình còn nhiều khó khăn, tôi chưa có khả năng tự chi trả các khoản chi phí khám sức khỏe. Vì vậy, sự hỗ trợ từ quỹ sẽ giúp tôi có cơ hội được kiểm tra sức khỏe đầy đủ, an tâm học tập, nâng cao chất lượng cuộc sống và tạo động lực tiếp tục phấn đấu đạt kết quả tốt trong học tập cũng như rèn luyện.', '50000000.00', 'Tai tro co thu hoi', '400000000.00', 'uploads/documents/TranNhutThienCV_1784354695435_490476562.pdf', 'DA_CHUYEN', 4, 11, NULL, NULL, 1, 'acc30a90-b348-4704-9bc6-7125afb3a8ee', '2026-07-18 06:05:22', '2026-07-18 06:05:26'),
(4, 'châu n gọc thúy', 'chaungocthuy910@gmail.com', '0378135232', 'sinh_vien', '12344556', 'công nghệ thông tin', 'da22 ttd', '0378135232', 'mb bank', 'CHAU N GOC THUY', 28, '[Đơn xin Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng cho sinh viên ngươi dân tộc] - CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM\nĐộc lập – Tự do – Hạnh phúc\n––––––––––––––––––––––––\n\nTrà Vinh, ngày [Ngày] tháng [Tháng] năm [Năm]\n\n**ĐƠN ĐỀ NGHỊ HỖ TRỢ KINH PHÍ NGHIÊN CỨU**\n\n**Kính gửi:**\n*   Ban Giám hiệu Trường Đại học Trà Vinh\n*   Ban Điều hành Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng\n\nTôi tên là: **[Điền Họ và tên]**\nMã số sinh viên: **[Điền MSSV]**\nLớp: **[Điền Lớp]**\nKhoa: **[Điền Khoa]**\nSố điện thoại: **[Điền SĐT]**\nEmail: **[Điền Email]**\n\nThay mặt nhóm nghiên cứu, tôi xin trân trọng kính gửi Đơn đề nghị này với mong muốn được Quý Ban xem xét, quan tâm và hỗ trợ kinh phí cho đề tài/dự án nghiên cứu của nhóm chúng tôi.\n\nHiện tại, nhóm chúng tôi, gồm các sinh viên thuộc Trường Đại học Trà Vinh, đang ấp ủ và trong quá trình chuẩn bị triển khai một dự án nghiên cứu y tế cộng đồng đầy tâm huyết. Mục tiêu chính của dự án là tổ chức các hoạt động khám bệnh, tư vấn sức khỏe và sàng lọc ban đầu cho đối tượng sinh viên có hoàn cảnh khó khăn, đặc biệt là sinh viên thuộc cộng đồng dân tộc thiểu số đang theo học tại Trường Đại học Trà Vinh.\n\nQua khảo sát, nhóm chúng tôi nhận thấy rằng, một bộ phận đáng kể sinh viên, đặc biệt là các em đến từ cộng đồng dân tộc thiểu số, thường gặp nhiều trở ngại trong việc tiếp cận các dịch vụ chăm sóc sức khỏe đầy đủ do điều kiện kinh tế khó khăn và khoảng cách địa lý. Việc thiếu kinh phí hiện là rào cản lớn nhất, gây khó khăn cho nhóm chúng tôi trong việc chuẩn bị các vật tư, thiết bị y tế thiết yếu, chi phí đi lại đến các khu vực có sinh viên dân tộc thiểu số, cũng như kinh phí tổ chức các buổi khám bệnh và phân tích dữ liệu cần thiết để đề tài nghiên cứu đạt hiệu quả tối ưu.\n\nChúng tôi tin rằng, dự án này không chỉ là một hoạt động nghiên cứu khoa học đơn thuần mà còn mang ý nghĩa nhân văn sâu sắc, góp phần trực tiếp vào việc cải thiện chất lượng cuộc sống, nâng cao nhận thức về sức khỏe cho cộng đồng sinh viên, đặc biệt là nhóm đối tượng dễ bị tổn thương tại trường. Đây cũng là hoạt động thiết thực, phù hợp với định hướng ưu tiên của Quỹ trong việc hỗ trợ các mô hình chăm sóc sức khỏe cộng đồng, đặc biệt là đối với cộng đồng dân tộc Khmer sinh sống tại tỉnh Trà Vinh và các tỉnh lân cận.\n\nQua tìm hiểu về Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng, chúng tôi nhận thấy mục tiêu và định hướng của Quỹ hoàn toàn phù hợp với dự án mà nhóm chúng tôi đang theo đuổi. Chúng tôi cam kết sẽ nghiêm túc thực hiện và tuân thủ mọi quy định của Quỹ, bao gồm việc chuẩn bị đầy đủ Thuyết minh đề tài/dự án nghiên cứu kèm dự toán kinh phí chi tiết, hồ sơ chấp thuận của Hội đồng Đạo đức nghiên cứu Y sinh học (trong trường hợp có liên quan đến đối tượng nghiên cứu là con người/động vật), và báo cáo tiến độ định kỳ theo yêu cầu. Nhóm cũng cam kết đảm bảo tính an toàn của các hoạt động và kết quả nghiên cứu.\n\nVới bản chất là một đề tài nghiên cứu vì cộng đồng, phi lợi nhuận thuần túy, không hướng đến mục tiêu thương mại hóa, chúng tôi kính đề nghị Ban Điều hành Quỹ xem xét áp dụng mức thu hồi 0% hoặc xem xét chuyển đổi hình thức sang tài trợ không hoàn lại toàn phần, căn cứ theo Điều 15, Khoản 1 Điều lệ Quỹ. Tuy nhiên, trong trường hợp đề xuất này không phù hợp với các tiêu chí của Quỹ, nhóm chúng tôi cũng hoàn toàn sẵn sàng thực hiện nghĩa vụ hoàn trả kinh phí đã được hỗ trợ theo đúng quy định và thời hạn tối đa 30 tháng kể từ khi dự án có khả năng tạo ra sản phẩm/dịch vụ có thu phí (nếu có).\n\nChúng tôi vô cùng kính mong nhận được sự quan tâm, ủng hộ và hỗ trợ kinh phí từ Quý Ban để đề tài của chúng tôi sớm được triển khai hiệu quả, góp phần mang lại những giá trị thiết thực cho cộng đồng sinh viên Trường Đại học Trà Vinh.\n\nChúng tôi xin chân thành bày tỏ lòng cảm ơn sâu sắc.\n\nTrân trọng kính chào,\nĐại diện nhóm nghiên cứu\n*(Ký và ghi rõ họ tên)*\n**[Điền Họ và tên]**', '30000000.00', 'Tai tro co thu hoi', '400000000.00', 'uploads/documents/TranNhutThienCV_1784645833941_559803345.pdf', 'DA_CHUYEN', 5, 13, NULL, NULL, 1, 'a941c8e0-a5a7-4bc3-8bea-b9ee9573af85', '2026-07-21 14:57:52', '2026-07-21 14:57:56'),
(5, 'Trần Nhựt Thiên', 'trannhutthien012345@gmail.com', '0363489827', 'sinh_vien', '110122162', 'Công nghệ Thông tin', 'DA22TTC', '0987654321', 'BIDV', 'TRAN NHUT THIEN', 28, '[Đơn xin Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng học kỳ II năm học 2026-2027] - vì không đủ kinh phí cho việc nghiên cứu và triển khai thực hiện nên cần sự chung tay giúp sức nguồn lục từ quỹ phát triển đại học trà vinh', '40000000.00', 'Tai tro co thu hoi', '200000000.00', 'uploads/documents/TranNhutThienCV_1785129579682_759494869.pdf', 'DA_CHUYEN', 6, 14, NULL, NULL, 1, 'd91bf754-73d6-4c8d-bbf4-e0d956e7ca19', '2026-07-27 05:20:10', '2026-07-27 05:20:13'),
(6, 'Nguyễn minh thiện', 'nthienwww@gmail.com', '0232463672', 'can_bo_nghi_huu', '012340234034', 'Khoa công nghệ thông tin', '20', '1234567876545', 'VietcoomBank', 'NGUYEN MINH THIEN', 27, '[Đơn xin hổ trợ vay vốn cho kế hoạch phát triển mô hình làm mát phun xương tự động] - Do thiếu hụt kinh phí cần thiết để triển khai mô hình làm mát tự động công nghệ cao ứng dụng công nghệ phun sương, tôi trân trọng kính đề nghị Quỹ Vay vốn Nông nghiệp Công nghệ cao xem xét và hỗ trợ.', '50000000.00', 'Cho vay', NULL, 'uploads/documents/TranNhutThienCV_1785140552336_766513976.pdf', 'DA_CHUYEN', 9, 17, NULL, NULL, 1, '3e73cd9d-a2a1-4999-b354-0500cba03a1e', '2026-07-27 08:23:30', '2026-07-27 08:23:33');

-- ------------------------------------------------------
-- Table structure for table `hopdongvayvon`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `hopdongvayvon`;
CREATE TABLE `hopdongvayvon` (
  `hopdongvayvon_id` int NOT NULL AUTO_INCREMENT,
  `yeucauhotro_id` int NOT NULL,
  `sotienvon` decimal(15,2) NOT NULL,
  `laisuatphantram` decimal(5,2) NOT NULL DEFAULT '0.00',
  `ngaykyhopdong` date NOT NULL,
  `kyhandothang` int NOT NULL,
  `ngaydaohan` date NOT NULL,
  `trangthai` enum('Dang thuc hien','Da tat toan','Qua han') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Dang thuc hien',
  `filehopdong` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nguoiduyet_id` int DEFAULT NULL,
  `ghichu` text COLLATE utf8mb4_unicode_ci,
