(2, 9, '50000000.00', '1.80', '2026-07-28', 10, '2027-05-28', 'Dang thuc hien', NULL, 1, 'Thuộc đối tượng được hỗ trợ theo Điều 5 Điều lệ Quỹ.\nHồ sơ đầy đủ, đúng mẫu theo quy định.\nNội dung đề nghị phù hợp mục đích hoạt động của Quỹ.\nĐáp ứng đầy đủ điều kiện xét hỗ trợ theo Điều 7 Điều lệ.\nMức kinh phí đề nghị phù hợp với quy mô và nội dung dự án.\nYêu cầu nghiệm thu theo đúng cam kết sau khi giải ngân (Điều 15).', '2026-07-28 10:52:03', '2026-07-28 10:52:03');

-- ------------------------------------------------------
-- Table structure for table `khoantaitro`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `khoantaitro`;
CREATE TABLE `khoantaitro` (
