(80, NULL, 'API_TAO_MOI', 'api', NULL, 'POST /api/guest/yeu-cau - tác động dữ liệu thành công (201)', NULL, '{"method":"POST","path":"/api/guest/yeu-cau","statusCode":201,"durationMs":276,"params":{},"query":{},"body":{"guestHoTen":"Hà Văn Khâu","guestEmail":"khauha65@gmail.com","guestSoDienThoai":"0743836852","guestMssv":"110123274","guestKhoa":"Nông nghiệp Thủy sản","guestLop":"DA22TSB","guestSoTaiKhoan":"09876543210","guestNganHang":"MbBank","guestChuTaiKhoan":"HA VAN KHAU","quyId":27,"lyDo":"[Đơn xin hổ trợ vay vốn xây dựng mô hình trông cây công nghệ nhà kính] - Nhằm phát triển mô hình trồng cây trong nhà kính ứng dụng công nghệ cao, tôi đề nghị được vay vốn có thu hồi để đầu tư xây dựng hệ thống nhà kính, hệ thống tưới nhỏ giọt tự động, thiết bị kiểm soát nhiệt độ, độ ẩm và mua cây giống, vật tư nông nghiệp chất lượng cao. Việc đầu tư mô hình này giúp nâng cao năng suất, chất lượng nông sản, giảm thiểu ảnh hưởng của thời tiết, hạn chế sâu bệnh và tiết kiệm chi phí sản xuất trong dài hạn.\\n\\nSau khi mô hình đi vào hoạt động ổn định, nguồn thu từ việc sản xuất và tiêu thụ nông sản sẽ được sử dụng để hoàn trả khoản vay theo đúng thời hạn cam kết. Dự án không chỉ góp phần tạo nguồn thu nhập ổn định, nâng cao kỹ năng ứng dụng công nghệ cao trong nông nghiệp mà còn có tiềm năng mở rộng quy mô, tạo việc làm và đóng góp vào sự phát triển của nền nông nghiệp bền vững tại địa phương.","soTienDeNghi":50000000,"taiLieuDinhKem":"uploads/documents/TranNhutThienCV_1784354027388_352665590.pdf","loaiHoTro":"Tai tro co thu hoi","tongKinhPhiDuAn":300000000,"laDeTai":1,"formTimestamp":"2026-07-18T05:48:25.989Z"}}', '127.0.0.1', '2026-07-18 05:53:48'),
