(88, NULL, 'API_TAO_MOI', 'api', NULL, 'POST /api/guest/yeu-cau - tác động dữ liệu thành công (201)', NULL, '{"method":"POST","path":"/api/guest/yeu-cau","statusCode":201,"durationMs":267,"params":{},"query":{},"body":{"guestHoTen":"Thạch Phan Dựng","guestEmail":"ditden39@gmail.com","guestSoDienThoai":"0939964322","guestMssv":"1101132456","guestKhoa":"Y tế","guestLop":"DÁ22YTA","guestSoTaiKhoan":"0987654567876","guestNganHang":"VietcomBank","guestChuTaiKhoan":"THACH PHAN DUNG","quyId":28,"lyDo":"[Đơn xin Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng cho sinh viên nghèo] - Nhằm đảm bảo điều kiện học tập và nâng cao chất lượng cuộc sống cho sinh viên có hoàn cảnh khó khăn, tôi đề nghị được hỗ trợ chi phí khám sức khỏe định kỳ. Việc khám sức khỏe giúp phát hiện sớm các vấn đề về thể chất, từ đó có biện pháp điều trị và phòng ngừa kịp thời, giúp sinh viên duy trì sức khỏe ổn định để học tập và rèn luyện.\\n\\nDo điều kiện kinh tế gia đình còn nhiều khó khăn, tôi chưa có khả năng tự chi trả các khoản chi phí khám sức khỏe. Vì vậy, sự hỗ trợ từ quỹ sẽ giúp tôi có cơ hội được kiểm tra sức khỏe đầy đủ, an tâm học tập, nâng cao chất lượng cuộc sống và tạo động lực tiếp tục phấn đấu đạt kết quả tốt trong học tập cũng như rèn luyện.","soTienDeNghi":50000000,"taiLieuDinhKem":"uploads/documents/TranNhutThienCV_1784354695435_490476562.pdf","loaiHoTro":"Tai tro co thu hoi","tongKinhPhiDuAn":400000000,"laDeTai":1,"formTimestamp":"2026-07-18T06:00:33.262Z"}}', '127.0.0.1', '2026-07-18 06:04:56'),
