-- Table structure for table `phanbongansach`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `phanbongansach`;
CREATE TABLE `phanbongansach` (
  `phanbongansach_id` int NOT NULL AUTO_INCREMENT,
  `quy_nguon_id` int NOT NULL,
  `quy_dich_id` int NOT NULL,
  `sotien` decimal(15,2) NOT NULL,
  `soquyetdinh` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `filequyetdinh` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trangthai` enum('Cho duyet','Da duyet','Tu choi','Da thu hoi') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Cho duyet',
  `lydotuchoi` text COLLATE utf8mb4_unicode_ci,
  `nguoi_de_xuat_id` int NOT NULL,
  `nguoi_duyet_id` int DEFAULT NULL,
  `ngaydexuat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ngayduyet` timestamp NULL DEFAULT NULL,
  `ghichu` text COLLATE utf8mb4_unicode_ci,
  `namtaichinh` year DEFAULT NULL,
  PRIMARY KEY (`phanbongansach_id`)
);

