-- ------------------------------------------------------
-- Table structure for table `quy`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `quy`;
CREATE TABLE `quy` (
  `quy_id` int NOT NULL AUTO_INCREMENT,
  `quy_cha_id` int DEFAULT NULL,
  `tenquy` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `loaiquy_id` int NOT NULL,
  `mota` text COLLATE utf8mb4_unicode_ci,
  `hinhanh` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sotienmuctieu` decimal(15,2) DEFAULT '0.00',
  `sodu` decimal(15,2) DEFAULT '0.00',
  `sotienhotrotoida` decimal(15,2) DEFAULT NULL,
  `soluonghotrotoida` int DEFAULT NULL,
  `dieukienhotro` text COLLATE utf8mb4_unicode_ci,
  `ngaybatdau` date DEFAULT NULL,
  `ngayketthuc` date DEFAULT NULL,
  `trangthai` enum('Dang hoat dong','Tam dung','Da dong') COLLATE utf8mb4_unicode_ci DEFAULT 'Dang hoat dong',
  `nguoitao_id` int DEFAULT NULL,
  `ngaytao` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ngaycapnhat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `loaidieuhanh` enum('Tap trung - Be chung','Tap trung - Muc chi') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Tap trung - Be chung',
  PRIMARY KEY (`quy_id`),
  KEY `loaiquy_id` (`loaiquy_id`),
  KEY `nguoitao_id` (`nguoitao_id`),
  CONSTRAINT `quy_ibfk_1` FOREIGN KEY (`loaiquy_id`) REFERENCES `loaiquy` (`loaiquy_id`) ON UPDATE CASCADE,
  CONSTRAINT `quy_ibfk_2` FOREIGN KEY (`nguoitao_id`) REFERENCES `nguoidung` (`nguoidung_id`) ON DELETE SET NULL ON UPDATE CASCADE
);

INSERT INTO `quy` (`quy_id`, `quy_cha_id`, `tenquy`, `loaiquy_id`, `mota`, `hinhanh`, `sotienmuctieu`, `sodu`, `sotienhotrotoida`, `soluonghotrotoida`, `dieukienhotro`, `ngaybatdau`, `ngayketthuc`, `trangthai`, `nguoitao_id`, `ngaytao`, `ngaycapnhat`, `loaidieuhanh`) VALUES
(15, NULL, 'Quy Phat trien Dai hoc Tra Vinh', 7, 'Quy me phat trien Dai hoc Tra Vinh - tai tro hoc bong, nghien cuu, co so vat chat va cac hoat dong phat trien truong.', 'uploads/avatars/fund/250_1781674629998_996093529_1784353490446_705505398.jpg', '4000000000.00', '800000000.00', NULL, NULL, 'Sinh vien he chinh quy, co hoan canh kho khan, dat hoc bong hoac giai thuong hoc thuat cap truong tro len.', '2026-01-01', '2026-12-29', 'Dang hoat dong', 1, '2026-07-16 15:46:08', '2026-07-18 05:45:02', 'Tap trung - Be chung'),
(21, NULL, 'Quy Test Debug', 7, 'Mo ta test', NULL, '2000000000.00', '0.00', NULL, NULL, NULL, '2026-07-17', '2026-12-31', 'Da dong', 1, '2026-07-17 17:23:49', '2026-07-17 17:37:20', 'Tap trung - Be chung'),
(26, 15, 'Quỹ Chuyển giao Công nghệ & Ứng dụng thực tiễn', 2, 'Quỹ Chuyển giao Công nghệ & Ứng dụng thực tiễn được thành lập theo đúng tinh thần Điều 15, Khoản 3 của Điều lệ Quỹ Phát triển Đại học Trà Vinh, hướng đến việc hỗ trợ vốn cho các hoạt động hoàn thiện công nghệ, thử nghiệm sản xuất và thương mại hóa các kết quả nghiên cứu khoa học đã có tại nhà trường. Đây là quỹ hoạt động theo cơ chế cho vay có hoàn trả, với lãi suất ưu đãi thấp hơn đáng kể so với lãi suất vay thương mại thông thường, nhằm giảm gánh nặng tài chính cho nhóm nghiên cứu, đồng thời đảm bảo nguồn vốn của Quỹ được luân chuyển bền vững để tiếp tục hỗ trợ các dự án tiếp theo. Đối tượng phục vụ chính của Quỹ là các nhóm nghiên cứu, giảng viên, cán bộ khoa học đã có sản phẩm nghiên cứu ở giai đoạn phòng thí nghiệm hoặc mô hình thử nghiệm nhỏ, mong muốn được hỗ trợ vốn để hoàn thiện quy trình sản xuất, kiểm định chất lượng và đưa sản phẩm ra thị trường ở quy mô lớn hơn. Quỹ đặc biệt khuyến khích các dự án có tính ứng dụng cao, gắn với thế mạnh nông nghiệp - thủy sản của khu vực Đồ', 'uploads/avatars/fund/HB-2025_1781675740918_210848626_1784309720136_369815023.jpg', '500000000.00', '200000000.00', '20000000.00', 25, '''ĐIỀU KIỆN VAY VỐN:\n- Chủ dự án là giảng viên, cán bộ nghiên cứu cơ hữu của Trường Đại học Trà Vinh, hoặc nhóm sinh viên có giảng viên hướng dẫn trực tiếp bảo trợ chuyên môn.\n- Dự án đã có kết quả nghiên cứu bước đầu (đề tài đã nghiệm thu cấp Trường trở lên, hoặc có minh chứng thử nghiệm quy mô phòng thí nghiệm đạt kết quả khả quan).\n- Có thuyết minh dự án hoàn thiện công nghệ/thương mại hóa rõ ràng, nêu cụ thể: quy trình công nghệ dự kiến hoàn thiện, kế hoạch sản xuất thử, dự kiến thị trường tiêu thụ và phương án hoàn trả vốn vay.\n- Cam kết bằng văn bản về tiến độ triển khai và kế hoạch trả nợ gốc, lãi theo đúng lịch trình được phê duyệt trong hợp đồng vay vốn.\n\nĐIỀU KIỆN VỀ LÃI SUẤT VÀ THỜI HẠN:\n- Lãi suất cho vay áp dụng tối đa không vượt quá 70% lãi suất cho vay của ngân hàng thương mại tại cùng thời điểm ký hợp đồng, đúng theo quy định tại Điều 15 Điều lệ Quỹ. Mức lãi suất cụ thể cho từng dự án do Quản trị viên xem xét, quyết định căn cứ vào mức độ rủi ro và quy mô vốn vay.\n- Thời hạn vay tối đa 24 tháng, có thể xem xét gia hạn thêm không quá 6 tháng trong trường hợp có lý do khách quan, chính đáng, được Ban Điều hành Quỹ chấp thuận.\n- Hình thức trả nợ: trả góp gốc và lãi hàng tháng hoặc hàng quý theo lịch trả nợ được lập kèm hợp đồng vay vốn.\n\nHỒ SƠ CẦN CHUẨN BỊ:\n1. Đơn đề nghị vay vốn (nộp trực tuyến qua hệ thống).\n2. Thuyết minh dự án hoàn thiện công nghệ/ứng dụng, kèm minh chứng kết quả nghiên cứu ban đầu.\n3. Dự toán chi tiết kinh phí sử dụng vốn vay.\n4. Phương án hoàn trả vốn vay (nguồn thu dự kiến, tiến độ trả nợ).\n\nLƯU Ý QUAN TRỌNG:\n- Dự án vi phạm cam kết sử dụng vốn sai mục đích hoặc không đạt kết quả nghiệm thu (nếu thuộc diện bắt buộc nghiệm thu) có thể bị Quỹ xem xét đình chỉ giải ngân các đợt tiếp theo hoặc yêu cầu thu hồi trước hạn theo quy định tại Điều lệ.\n- Kết quả xét duyệt được công bố công khai trên Cổng thông tin điện tử của Quỹ, kèm danh sách và thành tích minh chứng (đã ẩn thông tin cá nhân nhạy cảm theo quy định bảo mật).', '2026-07-17', '2027-12-18', 'Dang hoat dong', 1, '2026-07-17 17:36:56', '2026-07-17 17:36:56', 'Tap trung - Muc chi'),
(27, 15, 'Quỹ Vay vốn Nông nghiệp Công nghệ cao', 11, 'Quỹ Vay vốn Nông nghiệp Công nghệ cao được thành lập nhằm hỗ trợ vốn vay ưu đãi cho sinh viên, giảng viên và nhóm nghiên cứu có dự án ứng dụng công nghệ vào sản xuất nông nghiệp, thủy sản tại khu vực Đồng bằng sông Cửu Long — thế mạnh đào tạo và nghiên cứu truyền thống của Trường Đại học Trà Vinh. Đây là quỹ hoạt động theo cơ chế cho vay có hoàn trả gốc và lãi, hướng đến các mô hình khả thi về mặt kỹ thuật lẫn kinh tế: nuôi trồng thủy sản ứng dụng IoT giám sát môi trường, canh tác nhà màng - nhà lưới tiết kiệm nước, chế biến sâu nông sản sau thu hoạch, cơ giới hóa các khâu sản xuất nhỏ lẻ tại hộ gia đình. Quỹ được xây dựng dựa trên nguyên tắc "trao cần câu thay vì con cá", tạo điều kiện để người vay chủ động phát triển mô hình sản xuất, đồng thời có trách nhiệm hoàn trả vốn đúng hạn để Quỹ tiếp tục nhân rộng hỗ trợ cho các trường hợp khác trong những năm tiếp theo. Nguồn vốn của Quỹ được hình thành từ ngân sách đối ứng của Quỹ Phát triển Đại học Trà Vinh và các khoản tài trợ vốn mồi từ', 'uploads/avatars/fund/bvtv-640x427_1784352841835_11413823.jpg', '800000000.00', '450000000.00', '50000000.00', 16, '''ĐIỀU KIỆN VAY VỐN:\n- Người vay là sinh viên hệ chính quy (có giảng viên bảo trợ chuyên môn) hoặc giảng viên/cán bộ cơ hữu của Trường Đại học Trà Vinh có hộ khẩu/tạm trú tại khu vực Đồng bằng sông Cửu Long.\n- Có phương án sản xuất, kinh doanh cụ thể liên quan đến ứng dụng công nghệ trong nông nghiệp/thủy sản, nêu rõ: quy mô đầu tư, công nghệ áp dụng, dự kiến sản lượng/doanh thu và kế hoạch trả nợ.\n- Có tài sản hoặc phương án bảo đảm tối thiểu theo quy định riêng của Quỹ đối với các khoản vay từ 30.000.000đ trở lên (có thể là bảo lãnh của gia đình, giảng viên bảo trợ hoặc tài sản thế chấp tối thiểu).\n- Không đang có khoản vay quá hạn tại bất kỳ quỹ nào khác thuộc Quỹ Phát triển Đại học Trà Vinh.\n\nĐIỀU KIỆN VỀ LÃI SUẤT, THỜI HẠN VÀ TRẢ NỢ:\n- Lãi suất cho vay áp dụng tối đa không vượt quá 70% lãi suất cho vay của ngân hàng thương mại tại cùng thời điểm ký hợp đồng (theo Điều 15 Điều lệ Quỹ), riêng đối với các mô hình ứng dụng công nghệ cao có tính đổi mới sáng tạo rõ rệt, Ban Điều hành Quỹ có thể xem xét áp dụng mức lãi suất 0% trong 6 tháng đầu tiên.\n- Thời hạn vay tối đa 18 tháng đối với mô hình sản xuất theo mùa vụ, hoặc tối đa 24 tháng đối với mô hình đầu tư thiết bị, cơ sở hạ tầng lâu dài.\n- Trả nợ gốc và lãi theo kỳ hạn hàng tháng hoặc theo chu kỳ thu hoạch (đối với mô hình nông nghiệp theo mùa vụ), được thỏa thuận cụ thể và ghi rõ trong hợp đồng vay vốn.\n- Khoản vay quá hạn chịu lãi suất phạt tối đa gấp 2 lần lãi suất vay đã ký kết, tính từ ngày phát sinh quá hạn thực tế đến ngày thanh toán đầy đủ.\n\nHỒ SƠ CẦN CHUẨN BỊ:\n1. Đơn đề nghị vay vốn (nộp trực tuyến qua hệ thống).\n2. Phương án sản xuất, kinh doanh chi tiết (mô tả kỹ thuật, dự toán chi phí, dự kiến doanh thu).\n3. Giấy xác nhận bảo trợ chuyên môn của giảng viên (nếu người vay là sinh viên).\n4. Giấy tờ liên quan đến tài sản/phương án bảo đảm (nếu khoản vay từ 30.000.000đ trở lên).\n\nLƯU Ý:\n- Trong thời gian vay vốn, người vay có trách nhiệm báo cáo tiến độ triển khai mô hình định kỳ 3 tháng/lần cho Cán bộ Quỹ phụ trách.\n- Trường hợp sử dụng vốn sai mục đích đã cam kết trong phương án, Quỹ có quyền thu hồi toàn bộ khoản vay trước hạn theo quy định tại Điều lệ.', '2026-07-18', '2028-02-17', 'Dang hoat dong', 3, '2026-07-18 05:32:33', '2026-07-28 14:29:45', 'Tap trung - Muc chi'),
(28, 15, 'Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng', 10, 'Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng được thành lập nhằm hỗ trợ kinh phí cho các đề tài, dự án nghiên cứu khoa học thuộc lĩnh vực y tế, dược liệu, chăm sóc sức khỏe cộng đồng có tiềm năng phát triển thành sản phẩm ứng dụng thực tiễn (thực phẩm chức năng, dược liệu chế biến, quy trình chăm sóc sức khỏe cộng đồng có thể triển khai nhân rộng). Đây là quỹ hoạt động theo hình thức tài trợ có thu hồi một phần, phù hợp với các dự án nghiên cứu có chi phí đầu tư ban đầu tương đối lớn (thiết bị xét nghiệm, nguyên liệu dược tính, chi phí thử nghiệm lâm sàng/tiền lâm sàng ở quy mô nhỏ) nhưng có khả năng tạo ra sản phẩm thương mại hóa hoặc dịch vụ có thu phí sau khi hoàn thành. Quỹ đặc biệt ưu tiên các đề tài khai thác giá trị dược liệu bản địa của khu vực Đồng bằng sông Cửu Long, cũng như các mô hình chăm sóc sức khỏe phù hợp với đặc thù cộng đồng dân tộc Khmer sinh sống tại tỉnh Trà Vinh và các tỉnh lân cận.', 'uploads/avatars/fund/co-so-vat-chat_1784352949408_548512221.jpg', '900000000.00', '450000000.00', '50000000.00', 18, '''ĐIỀU KIỆN CHUNG:\n- Đề tài/dự án do giảng viên, cán bộ nghiên cứu cơ hữu hoặc nhóm sinh viên (có giảng viên hướng dẫn thuộc chuyên ngành Y - Dược, Sinh học, Công nghệ thực phẩm) chủ trì thực hiện.\n- Đề tài phải thuộc lĩnh vực y tế, dược liệu hoặc chăm sóc sức khỏe cộng đồng, có thuyết minh khoa học rõ ràng về cơ sở lý luận, phương pháp nghiên cứu và khả năng ứng dụng thực tiễn.\n- Các nghiên cứu liên quan đến thử nghiệm trên người hoặc động vật phải có đầy đủ hồ sơ đạo đức nghiên cứu được Hội đồng Đạo đức trong nghiên cứu Y sinh học của Trường (hoặc đơn vị có thẩm quyền tương đương) thông qua trước khi nộp hồ sơ xin tài trợ.\n\nMỨC THU HỒI VÀ NGHĨA VỤ HOÀN TRẢ (theo Điều 15, Khoản 1 Điều lệ Quỹ):\n- Mức thu hồi tối đa không vượt quá 30% tổng kinh phí thực hiện dự án đã được phê duyệt.\n- Nghĩa vụ hoàn trả phát sinh kể từ thời điểm sản phẩm/dịch vụ nghiên cứu bắt đầu được thương mại hóa hoặc triển khai thu phí, thời hạn hoàn trả tối đa 30 tháng kể từ ngày ký hợp đồng tài trợ (do đặc thù nghiên cứu y tế thường có chu kỳ kiểm định, cấp phép lâu hơn các lĩnh vực khác).\n- Đối với các đề tài mang tính phục vụ cộng đồng phi lợi nhuận thuần túy (không hướng đến thương mại hóa, ví dụ: mô hình khám sàng lọc miễn phí cho đồng bào dân tộc), Ban Điều hành Quỹ xem xét áp dụng mức thu hồi 0% hoặc chuyển sang hình thức tài trợ không hoàn lại toàn phần, dựa trên đề xuất cụ thể của nhóm nghiên cứu.\n\nQUY TRÌNH KIỂM TRA - NGHIỆM THU:\n- Do tính chất đặc thù của nghiên cứu y tế, dự án bắt buộc trải qua tối thiểu 2 lần kiểm tra tiến độ (giai đoạn nghiên cứu thử nghiệm và giai đoạn hoàn thiện sản phẩm) trước khi tiến hành nghiệm thu cuối cùng.\n- Kết quả nghiệm thu phải kèm theo minh chứng về tính an toàn của sản phẩm/quy trình (kết quả kiểm nghiệm, xác nhận của cơ quan chuyên môn có thẩm quyền nếu sản phẩm liên quan trực tiếp đến sức khỏe con người).\n\nHỒ SƠ CẦN NỘP:\n1. Đơn đề nghị tài trợ (nộp trực tuyến qua hệ thống).\n2. Thuyết minh đề tài/dự án nghiên cứu, kèm dự toán kinh phí chi tiết.\n3. Hồ sơ chấp thuận của Hội đồng Đạo đức nghiên cứu Y sinh học (đối với các nghiên cứu có liên quan).\n4. Lý lịch khoa học của chủ nhiệm đề tài và các thành viên tham gia chính.\n\nLƯU Ý:\n- Sản phẩm nghiên cứu liên quan đến sức khỏe cộng đồng, trước khi đưa vào thương mại hóa hoặc phổ biến rộng rãi, phải tuân thủ đầy đủ quy định pháp luật hiện hành về an toàn thực phẩm, dược phẩm (nếu có) — trách nhiệm này thuộc về nhóm thực hiện đề tài, không thuộc phạm vi bảo đảm của Quỹ.\n- Nhóm nghiên cứu có trách nhiệm báo cáo tiến độ định kỳ 3 tháng/lần và thông báo ngay cho Cán bộ Quỹ phụ trách nếu phát sinh vấn đề liên quan đến an toàn trong quá trình thử nghiệm.', '2026-07-18', '2028-04-18', 'Dang hoat dong', 3, '2026-07-18 05:37:09', '2026-07-20 09:05:55', 'Tap trung - Muc chi');

-- ------------------------------------------------------
-- Table structure for table `sinhviennoibat`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `sinhviennoibat`;
CREATE TABLE `sinhviennoibat` (
  `sinhviennoibat_id` int NOT NULL AUTO_INCREMENT,
  `nguoidung_id` int DEFAULT NULL,
  `hoten` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `khoaphong` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `namhoc` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hinhanh` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `thanhtich` text COLLATE utf8mb4_unicode_ci,
  `thutu` int DEFAULT '0',
  `trangthai` enum('Hien thi','An') COLLATE utf8mb4_unicode_ci DEFAULT 'Hien thi',
  `ngaytao` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ngaycapnhat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`sinhviennoibat_id`),
  KEY `idx_thutu` (`thutu`),
  KEY `nguoidung_id` (`nguoidung_id`),
  CONSTRAINT `sinhviennoibat_ibfk_1` FOREIGN KEY (`nguoidung_id`) REFERENCES `nguoidung` (`nguoidung_id`) ON DELETE SET NULL ON UPDATE CASCADE
);

-- ------------------------------------------------------
-- Table structure for table `taikhoannganhang`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `taikhoannganhang`;
CREATE TABLE `taikhoannganhang` (
  `taikhoannganhang_id` int NOT NULL AUTO_INCREMENT,
  `quy_id` int DEFAULT NULL,
  `loaitaikhoan` enum('Nha truong','Sinh vien') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Sinh vien',
  `sotaikhoan` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nganhang` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chinhanh` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chutaikhoan` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `trangthai` enum('Hoat dong','Khoa') COLLATE utf8mb4_unicode_ci DEFAULT 'Hoat dong',
  `ngaytao` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ngaycapnhat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`taikhoannganhang_id`),
  KEY `idx_quy` (`quy_id`),
  KEY `idx_loaitaikhoan` (`loaitaikhoan`,`trangthai`),
  CONSTRAINT `taikhoannganhang_ibfk_1` FOREIGN KEY (`quy_id`) REFERENCES `quy` (`quy_id`) ON DELETE CASCADE ON UPDATE CASCADE
);

INSERT INTO `taikhoannganhang` (`taikhoannganhang_id`, `quy_id`, `loaitaikhoan`, `sotaikhoan`, `nganhang`, `chinhanh`, `chutaikhoan`, `trangthai`, `ngaytao`, `ngaycapnhat`) VALUES
