-- ------------------------------------------------------
-- Table structure for table `tintuc`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `tintuc`;
CREATE TABLE `tintuc` (
  `tintuc_id` int NOT NULL AUTO_INCREMENT,
  `tieude` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `motangan` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `noidung` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nội dung đầy đủ bài viết (có thể chứa HTML/Markdown)',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Đường dẫn ảnh thumbnail hiển thị ở card tin tức',
  `danhmuc` enum('Tin hoc bong','Tin giao duc','Su kien','Thong bao','Bao cao hoat dong','Khac') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Thong bao',
  `phanloai` enum('Tin moi','Tin noi bat','baocaohoatdong','chuongtrinh','cuusinhvien') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Tin moi',
  `lanoibat` tinyint DEFAULT '0' COMMENT '0=Bình thường, 1=Featured lớn, 2=Featured nhỏ hàng dưới, 3=Sidebar',
  `trangthai` enum('Ban nhap','Da xuat ban','Da an') COLLATE utf8mb4_unicode_ci DEFAULT 'Ban nhap',
  `ngayxuatban` timestamp NULL DEFAULT NULL,
  `nguoitao_id` int NOT NULL COMMENT 'Admin hoặc Cán bộ tạo bài viết',
  `nguoisua_id` int DEFAULT NULL COMMENT 'Người chỉnh sửa lần cuối',
  `ngaytao` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ngaycapnhat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`tintuc_id`),
  KEY `idx_trangthai` (`trangthai`),
  KEY `idx_danhmuc` (`danhmuc`),
  KEY `idx_noi_bat` (`lanoibat`),
  KEY `idx_ngayxuatban` (`ngayxuatban`),
  KEY `idx_nguoitao` (`nguoitao_id`),
  KEY `nguoisua_id` (`nguoisua_id`),
  CONSTRAINT `tintuc_ibfk_1` FOREIGN KEY (`nguoitao_id`) REFERENCES `nguoidung` (`nguoidung_id`) ON UPDATE CASCADE,
  CONSTRAINT `tintuc_ibfk_2` FOREIGN KEY (`nguoisua_id`) REFERENCES `nguoidung` (`nguoidung_id`) ON DELETE SET NULL ON UPDATE CASCADE
);

INSERT INTO `tintuc` (`tintuc_id`, `tieude`, `motangan`, `noidung`, `avatar`, `danhmuc`, `phanloai`, `lanoibat`, `trangthai`, `ngayxuatban`, `nguoitao_id`, `nguoisua_id`, `ngaytao`, `ngaycapnhat`) VALUES
(7, 'Thông báo mở đợt xét duyệt Học bổng Khuyến học học kỳ II năm học 2025-2026', 'Quỹ Phát triển Đại học Trà Vinh chính thức mở đợt tiếp nhận hồ sơ xin hỗ trợ học bổng khuyến học học kỳ II năm học 2025-2026 dành cho sinh viên có hoàn cảnh khó khăn, kể từ ngày 20/07/2026 đến hết ngày 20/08/2026.', '<p><strong>1.&nbsp;Mục&nbsp;đích</strong></p><p>Nhằm&nbsp;tiếp&nbsp;tục&nbsp;thực&nbsp;hiện&nbsp;Điều&nbsp;lệ&nbsp;Quỹ&nbsp;Phát&nbsp;triển&nbsp;Đại&nbsp;học&nbsp;Trà&nbsp;Vinh&nbsp;(TVU&nbsp;Fund)&nbsp;về&nbsp;hỗ&nbsp;trợ&nbsp;sinh&nbsp;viên&nbsp;có&nbsp;hoàn&nbsp;cảnh&nbsp;khó&nbsp;khăn,&nbsp;có&nbsp;ý&nbsp;chí&nbsp;vươn&nbsp;lên&nbsp;trong&nbsp;học&nbsp;tập,&nbsp;Quỹ&nbsp;Phát&nbsp;triển&nbsp;Đại&nbsp;học&nbsp;Trà&nbsp;Vinh&nbsp;thông&nbsp;báo&nbsp;mở&nbsp;đợt&nbsp;tiếp&nbsp;nhận&nbsp;hồ&nbsp;sơ&nbsp;xin&nbsp;hỗ&nbsp;trợ&nbsp;Học&nbsp;bổng&nbsp;Khuyến&nbsp;học&nbsp;học&nbsp;kỳ&nbsp;II&nbsp;năm&nbsp;học&nbsp;2025-2026.</p><p><strong>2.&nbsp;Đối&nbsp;tượng&nbsp;áp&nbsp;dụng</strong></p><p>Sinh&nbsp;viên&nbsp;hệ&nbsp;chính&nbsp;quy&nbsp;đang&nbsp;theo&nbsp;học&nbsp;tại&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;Trà&nbsp;Vinh,&nbsp;có&nbsp;mã&nbsp;số&nbsp;sinh&nbsp;viên&nbsp;hợp&nbsp;lệ.</p><p>Thuộc&nbsp;diện&nbsp;hộ&nbsp;nghèo,&nbsp;cận&nbsp;nghèo,&nbsp;mồ&nbsp;côi&nbsp;cha&nbsp;hoặc&nbsp;mẹ&nbsp;(hoặc&nbsp;cả&nbsp;hai),&nbsp;gia&nbsp;đình&nbsp;gặp&nbsp;biến&nbsp;cố&nbsp;đột&nbsp;xuất&nbsp;(thiên&nbsp;tai,&nbsp;hỏa&nbsp;hoạn,&nbsp;tai&nbsp;nạn,&nbsp;bệnh&nbsp;hiểm&nbsp;nghèo...)</p><p>Có&nbsp;điểm&nbsp;trung&nbsp;bình&nbsp;học&nbsp;tập&nbsp;học&nbsp;kỳ&nbsp;gần&nbsp;nhất&nbsp;đạt&nbsp;từ&nbsp;6.5&nbsp;trở&nbsp;lên,&nbsp;không&nbsp;vi&nbsp;phạm&nbsp;quy&nbsp;chế&nbsp;học&nbsp;vụ&nbsp;và&nbsp;nội&nbsp;quy&nbsp;nhà&nbsp;trường.</p><p><strong>3.&nbsp;Mức&nbsp;hỗ&nbsp;trợ</strong></p><p>Căn&nbsp;cứ&nbsp;theo&nbsp;tình&nbsp;hình&nbsp;thực&nbsp;tế&nbsp;của&nbsp;quỹ&nbsp;và&nbsp;mức&nbsp;độ&nbsp;khó&nbsp;khăn&nbsp;của&nbsp;từng&nbsp;hồ&nbsp;sơ,&nbsp;mức&nbsp;hỗ&nbsp;trợ&nbsp;dao&nbsp;động&nbsp;từ&nbsp;5.000.000đ&nbsp;đến&nbsp;15.000.000đ/sinh&nbsp;viên/lần,&nbsp;không&nbsp;vượt&nbsp;quá&nbsp;mức&nbsp;hỗ&nbsp;trợ&nbsp;tối&nbsp;đa&nbsp;quy&nbsp;định&nbsp;tại&nbsp;từng&nbsp;quỹ&nbsp;thành&nbsp;phần.</p><p><strong>4.&nbsp;Hồ&nbsp;sơ&nbsp;cần&nbsp;chuẩn&nbsp;bị</strong></p><p>Đơn&nbsp;xin&nbsp;hỗ&nbsp;trợ&nbsp;theo&nbsp;mẫu&nbsp;(nộp&nbsp;trực&nbsp;tuyến&nbsp;qua&nbsp;hệ&nbsp;thống&nbsp;TVU&nbsp;Fund&nbsp;Management).</p><p>Giấy&nbsp;xác&nbsp;nhận&nbsp;hoàn&nbsp;cảnh&nbsp;gia&nbsp;đình&nbsp;khó&nbsp;khăn&nbsp;của&nbsp;chính&nbsp;quyền&nbsp;địa&nbsp;phương&nbsp;(bản&nbsp;scan/ảnh&nbsp;chụp&nbsp;rõ&nbsp;nét).</p><p>Bảng&nbsp;điểm&nbsp;học&nbsp;kỳ&nbsp;gần&nbsp;nhất.</p><p>Các&nbsp;giấy&nbsp;tờ&nbsp;minh&nbsp;chứng&nbsp;khác&nbsp;liên&nbsp;quan&nbsp;đến&nbsp;hoàn&nbsp;cảnh&nbsp;(nếu&nbsp;có):&nbsp;giấy&nbsp;chứng&nbsp;tử,&nbsp;giấy&nbsp;xác&nbsp;nhận&nbsp;hộ&nbsp;nghèo/cận&nbsp;nghèo,&nbsp;giấy&nbsp;ra&nbsp;viện...</p><p><strong>5.&nbsp;Quy&nbsp;trình&nbsp;xét&nbsp;duyệt</strong></p><p>Hồ&nbsp;sơ&nbsp;sau&nbsp;khi&nbsp;nộp&nbsp;trên&nbsp;hệ&nbsp;thống&nbsp;sẽ&nbsp;được&nbsp;xét&nbsp;duyệt&nbsp;qua&nbsp;3&nbsp;cấp:&nbsp;Cán&nbsp;bộ&nbsp;Quỹ&nbsp;(cấp&nbsp;1)&nbsp;thẩm&nbsp;định&nbsp;tính&nbsp;hợp&nbsp;lệ&nbsp;của&nbsp;hồ&nbsp;sơ,&nbsp;Quản&nbsp;trị&nbsp;viên&nbsp;(cấp&nbsp;2)&nbsp;xét&nbsp;duyệt&nbsp;mức&nbsp;hỗ&nbsp;trợ,&nbsp;và&nbsp;Kế&nbsp;toán&nbsp;(cấp&nbsp;3)&nbsp;thực&nbsp;hiện&nbsp;giải&nbsp;ngân&nbsp;sau&nbsp;khi&nbsp;hồ&nbsp;sơ&nbsp;được&nbsp;thông&nbsp;qua.&nbsp;Thời&nbsp;gian&nbsp;xử&nbsp;lý&nbsp;dự&nbsp;kiến&nbsp;từ&nbsp;10-15&nbsp;ngày&nbsp;làm&nbsp;việc&nbsp;kể&nbsp;từ&nbsp;ngày&nbsp;nộp&nbsp;hồ&nbsp;sơ&nbsp;hợp&nbsp;lệ.</p><p><strong>6.&nbsp;Thời&nbsp;gian&nbsp;và&nbsp;kênh&nbsp;nộp&nbsp;hồ&nbsp;sơ</strong></p><p>Thời&nbsp;gian&nbsp;nhận&nbsp;hồ&nbsp;sơ:&nbsp;từ&nbsp;08h00&nbsp;ngày&nbsp;20/07/2026&nbsp;đến&nbsp;17h00&nbsp;ngày&nbsp;20/08/2026.&nbsp;Sinh&nbsp;viên&nbsp;nộp&nbsp;hồ&nbsp;sơ&nbsp;trực&nbsp;tuyến&nbsp;tại&nbsp;hệ&nbsp;thống&nbsp;Quản&nbsp;lý&nbsp;Quỹ&nbsp;Phát&nbsp;triển&nbsp;TVU&nbsp;(mục&nbsp;&quot;Nộp&nbsp;đơn&nbsp;xin&nbsp;hỗ&nbsp;trợ&quot;),&nbsp;chọn&nbsp;đúng&nbsp;Quỹ&nbsp;Học&nbsp;bổng&nbsp;Khuyến&nbsp;học&nbsp;TVU&nbsp;2025-2026.</p><p><em>Mọi&nbsp;thắc&nbsp;mắc&nbsp;xin&nbsp;liên&nbsp;hệ&nbsp;Văn&nbsp;phòng&nbsp;Quỹ&nbsp;Phát&nbsp;triển&nbsp;Đại&nbsp;học&nbsp;Trà&nbsp;Vinh,&nbsp;số&nbsp;điện&nbsp;thoại&nbsp;đường&nbsp;dây&nbsp;nóng&nbsp;hoặc&nbsp;email&nbsp;được&nbsp;công&nbsp;bố&nbsp;tại&nbsp;trang&nbsp;Cài&nbsp;đặt&nbsp;hệ&nbsp;thống&nbsp;trên&nbsp;Cổng&nbsp;thông&nbsp;tin&nbsp;TVU&nbsp;Fund.</em></p>', 'uploads/tintuc/HB7_1781675589859_499560317_1784307349234_413683028.jpg', 'Thong bao', 'Tin moi', 1, 'Da xuat ban', '2026-07-17 16:55:00', 1, NULL, '2026-07-17 17:01:50', '2026-07-17 17:01:50');

-- ------------------------------------------------------
-- Table structure for table `vaitro`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `vaitro`;
CREATE TABLE `vaitro` (
  `vaitro_id` int NOT NULL AUTO_INCREMENT,
  `tenvaitro` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mota` text COLLATE utf8mb4_unicode_ci,
  `trangthai` enum('Hoat dong','Tam dung') COLLATE utf8mb4_unicode_ci DEFAULT 'Hoat dong',
  `ngaytao` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ngaycapnhat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`vaitro_id`),
  UNIQUE KEY `uk_tenvaitro` (`tenvaitro`)
);

