-- ------------------------------------------------------
-- Table structure for table `yeucauhotro`
-- ------------------------------------------------------
DROP TABLE IF EXISTS `yeucauhotro`;
CREATE TABLE `yeucauhotro` (
  `yeucauhotro_id` int NOT NULL AUTO_INCREMENT,
  `nguoidung_id` int NOT NULL,
  `quy_id` int NOT NULL,
  `lydo` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `sotiendenghi` decimal(15,2) NOT NULL,
  `tailieudinhkem` text COLLATE utf8mb4_unicode_ci,
  `trangthai` enum('Cho duyet cap 1','Da duyet cap 1','Tu choi cap 1','Cho duyet cap 2','Da duyet cap 2','Tu choi cap 2','Cho duyet cap 3','Da duyet cap 3','Tu choi cap 3','Cho giai ngan','Da giai ngan','Cho nghiem thu','Da nghiem thu','Nghiem thu khong dat','Tu choi') COLLATE utf8mb4_unicode_ci DEFAULT 'Cho duyet cap 1',
  `ghichu` text COLLATE utf8mb4_unicode_ci,
  `ngaynop` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ngaycapnhat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `laidetac` tinyint(1) DEFAULT '0',
  `loaihotro` enum('Tai tro khong hoan lai','Tai tro co thu hoi','Cho vay') COLLATE utf8mb4_unicode_ci DEFAULT 'Tai tro khong hoan lai',
  `canghiemthu` tinyint(1) DEFAULT '0',
  `danhnghia` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tendaidien` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dot_id` int DEFAULT NULL,
  `tongkinhphidudan` decimal(15,2) DEFAULT NULL,
  PRIMARY KEY (`yeucauhotro_id`),
  KEY `idx_nguoidung` (`nguoidung_id`),
  KEY `idx_quy` (`quy_id`),
  KEY `idx_trangthai` (`trangthai`),
  CONSTRAINT `yeucauhotro_ibfk_1` FOREIGN KEY (`nguoidung_id`) REFERENCES `nguoidung` (`nguoidung_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `yeucauhotro_ibfk_2` FOREIGN KEY (`quy_id`) REFERENCES `quy` (`quy_id`) ON DELETE CASCADE ON UPDATE CASCADE
);

INSERT INTO `yeucauhotro` (`yeucauhotro_id`, `nguoidung_id`, `quy_id`, `lydo`, `sotiendenghi`, `tailieudinhkem`, `trangthai`, `ghichu`, `ngaynop`, `ngaycapnhat`, `laidetac`, `loaihotro`, `canghiemthu`, `danhnghia`, `tendaidien`, `dot_id`, `tongkinhphidudan`) VALUES
(4, 11, 28, '[Đơn xin Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng cho sinh viên nghèo] - Nhằm đảm bảo điều kiện học tập và nâng cao chất lượng cuộc sống cho sinh viên có hoàn cảnh khó khăn, tôi đề nghị được hỗ trợ chi phí khám sức khỏe định kỳ. Việc khám sức khỏe giúp phát hiện sớm các vấn đề về thể chất, từ đó có biện pháp điều trị và phòng ngừa kịp thời, giúp sinh viên duy trì sức khỏe ổn định để học tập và rèn luyện.\n\nDo điều kiện kinh tế gia đình còn nhiều khó khăn, tôi chưa có khả năng tự chi trả các khoản chi phí khám sức khỏe. Vì vậy, sự hỗ trợ từ quỹ sẽ giúp tôi có cơ hội được kiểm tra sức khỏe đầy đủ, an tâm học tập, nâng cao chất lượng cuộc sống và tạo động lực tiếp tục phấn đấu đạt kết quả tốt trong học tập cũng như rèn luyện.', '50000000.00', 'uploads/documents/TranNhutThienCV_1784354695435_490476562.pdf', 'Da giai ngan', NULL, '2026-07-18 06:05:25', '2026-07-28 07:05:35', 0, 'Tai tro co thu hoi', 0, NULL, NULL, 8, '400000000.00'),
(6, 14, 28, '[Đơn xin Quỹ Tài trợ Có thu hồi - Nghiên cứu Y tế & Sức khỏe cộng đồng học kỳ II năm học 2026-2027] - vì không đủ kinh phí cho việc nghiên cứu và triển khai thực hiện nên cần sự chung tay giúp sức nguồn lục từ quỹ phát triển đại học trà vinh', '40000000.00', 'uploads/documents/TranNhutThienCV_1785129579682_759494869.pdf', 'Cho duyet cap 3', NULL, '2026-07-27 05:20:12', '2026-07-28 14:20:52', 0, 'Tai tro co thu hoi', 1, NULL, NULL, 8, '200000000.00'),
(7, 15, 27, 'vì không đủ kinh phí cho dự án trồng dâu đà lạt trong nhà kính ở trà vinh nên cần sự chung tay gốp sức hổ trợ của quỹ phát triển đại học trà vinh', '50000000.00', 'uploads/documents/TranNhutThienCV_1785130069053_903549305.pdf', 'Cho giai ngan', NULL, '2026-07-27 05:27:50', '2026-07-28 14:01:57', 1, 'Cho vay', 1, NULL, NULL, 6, NULL),
(8, 16, 27, 'Do thiếu hụt kinh phí, tôi kính mong nhận được sự hỗ trợ từ Quỹ Vay vốn Nông nghiệp Công nghệ cao để triển khai mô hình nuôi tôm ứng dụng công nghệ cao. Mô hình này tích hợp giải pháp tự động hóa toàn diện trong quy trình thay nước và cho tôm ăn, hứa hẹn mang lại hiệu quả sản xuất vượt trội.', '50000000.00', 'uploads/documents/TranNhutThienCV_1785140181922_197431165.pdf', 'Cho giai ngan', NULL, '2026-07-27 08:16:23', '2026-07-28 11:02:43', 1, 'Cho vay', 1, NULL, NULL, 6, NULL),
(9, 17, 27, '[Đơn xin hổ trợ vay vốn cho kế hoạch phát triển mô hình làm mát phun xương tự động] - Do thiếu hụt kinh phí cần thiết để triển khai mô hình làm mát tự động công nghệ cao ứng dụng công nghệ phun sương, tôi trân trọng kính đề nghị Quỹ Vay vốn Nông nghiệp Công nghệ cao xem xét và hỗ trợ.', '50000000.00', 'uploads/documents/TranNhutThienCV_1785140552336_766513976.pdf', 'Da nghiem thu', NULL, '2026-07-27 08:23:32', '2026-07-29 17:38:35', 0, 'Cho vay', 1, NULL, NULL, 6, NULL);

SET FOREIGN_KEY_CHECKS = 1;
